'use client'

import * as React from 'react'

import { useOffscreen } from './use-reduced-motion'
import './vortex.css'

export type VortexProps = React.ComponentPropsWithoutRef<'div'> & {
    colors?: [string, string]
    /** Seconds per turn. Keep it slow: spinning spirals can cause discomfort. */
    speed?: number
    paused?: boolean
}

// A slowly turning spiral of colour that fades toward the edges.
const Vortex = ({ colors = ['rgba(139, 92, 246, 0.45)', 'rgba(34, 211, 238, 0.25)'], speed = 30, paused = false, className, style, children, ...props }: VortexProps) => {
    const ref = React.useRef<HTMLDivElement | null>(null)
    const offscreen = useOffscreen(ref)

    return <div
        ref={ref}
        className={['rad-fx-vortex', className].filter(Boolean).join(' ')}
        data-state={paused || offscreen ? 'paused' : 'running'}
        style={{ '--rad-fx-vortex-a': colors[0], '--rad-fx-vortex-b': colors[1], '--rad-fx-vortex-speed': `${speed}s`, ...style } as React.CSSProperties}
        {...props}
    >
        <div className="rad-fx-vortex-layer" aria-hidden="true">
            <span className="rad-fx-vortex-swirl" />
        </div>
        <div className="rad-fx-vortex-content">{children}</div>
    </div>
}

export default Vortex

.rad-fx-vortex {
    position: relative;
    isolation: isolate;
    overflow: hidden;
}

.rad-fx-vortex-layer {
    position: absolute;
    inset: 0;
    z-index: -1;
    pointer-events: none;
}

.rad-fx-vortex-content { position: relative; }

.rad-fx-vortex[data-state='paused'] .rad-fx-vortex-layer,
.rad-fx-vortex[data-state='paused'] .rad-fx-vortex-layer * { animation-play-state: paused !important; }

.rad-fx-vortex-swirl {
    position: absolute;
    left: 50%;
    top: 50%;
    width: 180%;
    aspect-ratio: 1;
    translate: -50% -50%;
    background:
        repeating-conic-gradient(from 0deg, var(--rad-fx-vortex-a) 0deg 12deg, transparent 12deg 30deg, var(--rad-fx-vortex-b) 30deg 40deg, transparent 40deg 60deg);
    mask-image: radial-gradient(circle, #000 0%, transparent 55%);
    filter: blur(14px);
    animation: rad-fx-vortex var(--rad-fx-vortex-speed, 30s) linear infinite;
}

@keyframes rad-fx-vortex { to { transform: rotate(360deg); } }

@media (prefers-reduced-motion: reduce) {
    .rad-fx-vortex-swirl { animation: none; }
}

[data-rad-fx-motion='reduce'] .rad-fx-vortex-swirl { animation: none; }
